package cabinet

const invitationTemplates = `
{{define "invitations"}}{{template "head"}}<body><header><a class="brand" href="/">Среда</a><span>Администратор</span></header><main><h1>Приглашения пользователей</h1><p>Создайте одноразовую ссылку и лично передайте её человеку. Почта не отправляется.</p>{{if .InvitationLink}}<section class="card"><h2>Ссылка приглашения</h2><p><a href="{{.InvitationLink}}">{{.InvitationLink}}</a></p><p>Сохраните ссылку сейчас: повторно она не показывается.</p></section>{{end}}<section class="card"><form method="post" action="/admin/invitations"><input type="hidden" name="csrf" value="{{.CSRF}}"><label for="lifetime">Срок действия</label><select id="lifetime" name="lifetime"><option value="1h">1 час</option><option value="24h" selected>24 часа</option><option value="168h">7 дней</option></select><button type="submit">Создать приглашение</button></form><p>Открытие ссылки не использует приглашение. Оно расходуется только после успешного создания аккаунта. Закрытую форму можно открыть снова до истечения срока.</p></section>{{range .Invitations}}<section class="card"><p>Приглашение №{{.ID}} · {{.Status}}</p><p>Действует до {{.Expires}}</p>{{if .CanCancel}}<form method="post" action="/admin/invitations/{{.ID}}/cancel"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button type="submit">Отменить приглашение</button></form>{{end}}</section>{{end}}</main></body></html>{{end}}
{{define "invitation"}}{{template "head"}}<body><header><span class="brand">Среда</span></header><main><section class="card"><h1>Присоединиться к Среде</h1>{{if .Expires}}<p>Действует до {{.Expires}}</p>{{end}}<p>Задайте логин и пароль. Приглашение используется только после успешного создания аккаунта; незавершённую форму можно открыть снова до истечения срока.</p>{{if .Error}}<p class="error" role="alert">{{.Error}}</p>{{end}}<form method="post" action="/invite/{{.Token}}"><input type="hidden" name="csrf" value="{{.CSRF}}"><label for="login">Логин</label><input id="login" name="login" autocomplete="username" minlength="3" maxlength="64" required><label for="password">Пароль (12–72 байта)</label><input id="password" type="password" name="password" autocomplete="new-password" minlength="12" required><button class="submit" type="submit">Создать аккаунт</button></form></section></main></body></html>{{end}}
`
